CREATE TABLE "questionnaire_investisseur" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "questionnaire_investisseur_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"utilisateur_id" text NOT NULL,
	"etape_courante" integer DEFAULT 1 NOT NULL,
	"reponses" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"version_questionnaire" text NOT NULL,
	"cree_le" timestamp with time zone DEFAULT now() NOT NULL,
	"mis_a_jour_le" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "questionnaire_investisseur_utilisateur_id_unique" UNIQUE("utilisateur_id")
);
